[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --purple: oklch(44% 0.26 290);
      --purple-light: oklch(60% 0.22 290);
      --purple-pale: oklch(94% 0.04 290);
      --orange: oklch(72% 0.19 60);
      --orange-light: oklch(82% 0.14 60);
      --gradient: linear-gradient(135deg, oklch(44% 0.26 290), oklch(55% 0.24 320), oklch(72% 0.19 60));
      --gradient-subtle: linear-gradient(135deg, oklch(94% 0.06 290), oklch(96% 0.03 320), oklch(95% 0.04 60));
      --black: oklch(15% 0.02 290);
      --text-primary: oklch(15% 0.02 290);
      --text-secondary: oklch(45% 0.02 290);
      --text-muted: oklch(60% 0.01 290);
      --bg-white: oklch(100% 0 0);
      --bg-light: oklch(98% 0.005 290);
      --bg-surface: oklch(96% 0.005 290);
      --border: oklch(90% 0.01 290);
      --radius-sm: 8px;
      --radius-md: 14px;
      --radius-lg: 20px;
      --radius-xl: 28px;
      --radius-full: 9999px;
      --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.08);
      --shadow-md: 0 4px 16px oklch(0% 0 0 / 0.1);
      --shadow-lg: 0 8px 32px oklch(0% 0 0 / 0.12);
      --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      --container: 1200px;
      --transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
    }

    html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }

    body {
      font-family: var(--font);
      color: var(--text-primary);
      background: var(--bg-white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
      overflow-x: hidden;
    }

    a { color: inherit; text-decoration: none; }
    button { font-family: var(--font); cursor: pointer; border: none; background: none; }
    img { display: block; max-width: 100%; }
    ul { list-style: none; }

    .container { max-width: var(--container); margin: 0 auto; padding: 0 24px; }

    /* ============ HEADER ============ */
    .header {
      position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
      background: oklch(100% 0 0 / 0.92);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid var(--border);
      transition: background var(--transition);
    }
    .header-inner {
      display: flex; align-items: center; justify-content: space-between;
      height: 64px; max-width: var(--container); margin: 0 auto; padding: 0 24px;
    }
    .header-logo {
      font-weight: 800; font-size: 22px; letter-spacing: -0.5px;
      background: var(--gradient); -webkit-background-clip: text; -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .header-nav { display: flex; align-items: center; gap: 32px; }
    .header-nav a {
      font-size: 14px; font-weight: 500; color: var(--text-secondary);
      transition: color var(--transition);
    }
    .header-nav a:hover { color: var(--text-primary); }
    .btn-login {
      font-size: 14px; font-weight: 600; padding: 8px 20px;
      background: var(--black); color: var(--bg-white);
      border-radius: var(--radius-full); transition: all var(--transition);
    }
    .btn-login:hover { background: var(--purple); }

    .hamburger {
      display: none; flex-direction: column; gap: 5px;
      width: 28px; padding: 4px 0; cursor: pointer; background: none; border: none;
    }
    .hamburger span {
      display: block; width: 100%; height: 2.5px; border-radius: 2px;
      background: var(--text-primary); transition: all var(--transition);
    }
    .hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
    .hamburger.active span:nth-child(2) { opacity: 0; }
    .hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

    .mobile-nav {
      display: none; position: fixed; top: 64px; left: 0; right: 0; bottom: 0;
      background: var(--bg-white); z-index: 999;
      flex-direction: column; padding: 32px 24px; gap: 8px;
      opacity: 0; transform: translateY(-8px);
      transition: opacity 0.2s ease, transform 0.2s ease;
    }
    .mobile-nav.open { display: flex; opacity: 1; transform: translateY(0); }
    .mobile-nav a {
      font-size: 18px; font-weight: 600; padding: 12px 0;
      color: var(--text-primary); border-bottom: 1px solid var(--border);
    }

    @media (max-width: 768px) {
      .header-nav { display: none; }
      .hamburger { display: flex; }
    }

    /* ============ HERO ============ */
    .hero {
      min-height: 100vh; display: flex; align-items: center; justify-content: center;
      text-align: center; position: relative; overflow: hidden;
      padding: 120px 24px 80px;
      background: var(--bg-white);
    }
    .hero-bg {
      position: absolute; inset: 0; z-index: 0;
      background:
        radial-gradient(ellipse 80% 60% at 20% 30%, oklch(44% 0.26 290 / 0.12), transparent),
        radial-gradient(ellipse 70% 50% at 80% 60%, oklch(72% 0.19 60 / 0.1), transparent),
        radial-gradient(ellipse 60% 40% at 50% 80%, oklch(55% 0.24 320 / 0.08), transparent);
    }
    .hero-grid {
      position: absolute; inset: 0; z-index: 0;
      background-image:
        linear-gradient(var(--border) 1px, transparent 1px),
        linear-gradient(90deg, var(--border) 1px, transparent 1px);
      background-size: 80px 80px;
      opacity: 0.4;
      mask-image: radial-gradient(ellipse 70% 70% at center, black 20%, transparent 70%);
      -webkit-mask-image: radial-gradient(ellipse 70% 70% at center, black 20%, transparent 70%);
    }
    .hero-content { position: relative; z-index: 1; max-width: 820px; }
    .hero h1 {
      font-size: clamp(36px, 7vw, 72px); font-weight: 900; line-height: 1.05;
      letter-spacing: -2px; margin-bottom: 24px;
      background: linear-gradient(135deg, oklch(15% 0.02 290) 40%, oklch(44% 0.26 290) 100%);
      -webkit-background-clip: text; -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .hero p {
      font-size: clamp(16px, 2.2vw, 20px); color: var(--text-secondary);
      max-width: 560px; margin: 0 auto 40px; line-height: 1.6;
    }
    .btn-cta {
      display: inline-flex; align-items: center; gap: 8px;
      font-size: 16px; font-weight: 700; padding: 16px 36px;
      background: var(--gradient); color: var(--bg-white);
      border-radius: var(--radius-full); transition: all var(--transition);
      box-shadow: 0 4px 24px oklch(44% 0.26 290 / 0.3);
    }
    .btn-cta:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 32px oklch(44% 0.26 290 / 0.4);
    }
    .btn-cta svg { width: 18px; height: 18px; }

    .hero-float {
      position: absolute; border-radius: var(--radius-lg);
      overflow: hidden; box-shadow: var(--shadow-lg);
      animation: float 6s ease-in-out infinite;
    }
    .hero-float-1 {
      width: 180px; height: 240px; top: 15%; left: 5%;
      background: linear-gradient(135deg, oklch(60% 0.22 290), oklch(72% 0.19 60));
      animation-delay: 0s;
    }
    .hero-float-2 {
      width: 140px; height: 200px; bottom: 12%; right: 6%;
      background: linear-gradient(135deg, oklch(72% 0.19 60), oklch(55% 0.24 320));
      animation-delay: -2s;
    }
    .hero-float-3 {
      width: 100px; height: 140px; top: 25%; right: 12%;
      background: linear-gradient(135deg, oklch(55% 0.24 320), oklch(44% 0.26 290));
      animation-delay: -4s;
    }
    @keyframes float {
      0%, 100% { transform: translateY(0) rotate(0deg); }
      50% { transform: translateY(-16px) rotate(2deg); }
    }
    @media (max-width: 768px) {
      .hero-float { display: none; }
    }

    /* ============ SECTION BASE ============ */
    .section { padding: 100px 0; }
    .section-label {
      display: inline-block; font-size: 12px; font-weight: 700;
      text-transform: uppercase; letter-spacing: 1.5px;
      padding: 6px 14px; border-radius: var(--radius-full);
      margin-bottom: 20px;
    }

    /* ============ FEATURES ============ */
    .features {
      background: var(--bg-light);
      position: relative; overflow: hidden;
    }
    .features-inner {
      display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
    }
    .features-visual {
      position: relative; aspect-ratio: 4/3; border-radius: var(--radius-xl);
      overflow: hidden;
      background: linear-gradient(135deg, oklch(44% 0.26 290), oklch(55% 0.24 320));
      box-shadow: var(--shadow-lg);
    }
    .features-visual::before {
      content: ''; position: absolute; inset: 0;
      background:
        radial-gradient(circle at 30% 40%, oklch(72% 0.19 60 / 0.5), transparent 60%),
        radial-gradient(circle at 70% 70%, oklch(60% 0.22 290 / 0.4), transparent 50%);
    }
    .features-visual-icons {
      position: absolute; inset: 0; display: flex; flex-wrap: wrap;
      align-items: center; justify-content: center; gap: 20px; padding: 40px;
    }
    .features-icon-card {
      width: 90px; height: 90px; border-radius: var(--radius-lg);
      background: oklch(100% 0 0 / 0.2); backdrop-filter: blur(8px);
      display: flex; align-items: center; justify-content: center;
      font-size: 28px; color: white; font-weight: 700;
      box-shadow: 0 4px 16px oklch(0% 0 0 / 0.15);
    }
    .features-label { background: oklch(94% 0.06 290); color: var(--purple); }
    .features h2 {
      font-size: clamp(28px, 4vw, 44px); font-weight: 800;
      line-height: 1.15; letter-spacing: -1px; margin-bottom: 20px;
    }
    .features p {
      font-size: 17px; color: var(--text-secondary); line-height: 1.7;
      margin-bottom: 32px; max-width: 480px;
    }
    .link-arrow {
      display: inline-flex; align-items: center; gap: 6px;
      font-size: 16px; font-weight: 700; color: var(--purple);
      transition: gap var(--transition);
    }
    .link-arrow:hover { gap: 10px; }
    .link-arrow svg { width: 18px; height: 18px; }

    @media (max-width: 768px) {
      .features-inner { grid-template-columns: 1fr; gap: 40px; }
      .features-visual { max-height: 300px; }
    }

    /* ============ SAFETY ============ */
    .safety { background: var(--bg-white); }
    .safety-inner {
      display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
    }
    .safety-inner > :first-child { order: 2; }
    .safety-inner > :last-child { order: 1; }
    .safety-label { background: oklch(93% 0.05 140); color: oklch(50% 0.12 140); }
    .safety h2 {
      font-size: clamp(28px, 4vw, 44px); font-weight: 800;
      line-height: 1.15; letter-spacing: -1px; margin-bottom: 20px;
    }
    .safety p {
      font-size: 17px; color: var(--text-secondary); line-height: 1.7;
      margin-bottom: 32px; max-width: 480px;
    }
    .safety-link { color: oklch(50% 0.12 140); }
    .safety-visual {
      position: relative; aspect-ratio: 4/3; border-radius: var(--radius-xl);
      overflow: hidden;
      background: linear-gradient(135deg, oklch(92% 0.04 160), oklch(88% 0.06 140));
      display: flex; align-items: center; justify-content: center;
    }
    .safety-shield {
      width: 120px; height: 120px; border-radius: 50%;
      background: oklch(96% 0.03 140);
      display: flex; align-items: center; justify-content: center;
      box-shadow: 0 8px 32px oklch(50% 0.12 140 / 0.15);
    }
    .safety-shield svg { width: 56px; height: 56px; color: oklch(50% 0.12 140); }
    .safety-ring {
      position: absolute; border-radius: 50%;
      border: 2px solid oklch(50% 0.12 140 / 0.15);
    }
    .safety-ring-1 { width: 220px; height: 220px; animation: pulse-ring 4s ease-in-out infinite; }
    .safety-ring-2 { width: 320px; height: 320px; animation: pulse-ring 4s ease-in-out infinite 1s; }
    .safety-ring-3 { width: 420px; height: 420px; animation: pulse-ring 4s ease-in-out infinite 2s; }
    @keyframes pulse-ring {
      0%, 100% { opacity: 0.3; transform: scale(1); }
      50% { opacity: 0.6; transform: scale(1.03); }
    }

    @media (max-width: 768px) {
      .safety-inner { grid-template-columns: 1fr; gap: 40px; }
      .safety-inner > :first-child { order: 1; }
      .safety-inner > :last-child { order: 2; }
      .safety-visual { max-height: 300px; }
    }

    /* ============ CREATORS ============ */
    .creators {
      background: var(--bg-light); position: relative; overflow: hidden;
    }
    .creators-inner {
      display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
    }
    .creators-label { background: oklch(94% 0.08 60); color: var(--orange); }
    .creators h2 {
      font-size: clamp(28px, 4vw, 44px); font-weight: 800;
      line-height: 1.15; letter-spacing: -1px; margin-bottom: 20px;
    }
    .creators p {
      font-size: 17px; color: var(--text-secondary); line-height: 1.7;
      margin-bottom: 32px; max-width: 480px;
    }
    .creators-link { color: var(--orange); }
    .creators-visual {
      position: relative; aspect-ratio: 4/3; border-radius: var(--radius-xl);
      overflow: hidden;
      background: linear-gradient(135deg, oklch(72% 0.19 60), oklch(65% 0.22 340));
      box-shadow: var(--shadow-lg);
    }
    .creators-visual::before {
      content: ''; position: absolute; inset: 0;
      background: radial-gradient(circle at 50% 50%, oklch(100% 0 0 / 0.15), transparent 60%);
    }
    .creators-sparkle {
      position: absolute; font-size: 32px; color: oklch(100% 0 0 / 0.6);
      animation: sparkle 3s ease-in-out infinite;
    }
    .creators-sparkle:nth-child(1) { top: 20%; left: 25%; animation-delay: 0s; }
    .creators-sparkle:nth-child(2) { top: 40%; right: 20%; animation-delay: 0.8s; font-size: 24px; }
    .creators-sparkle:nth-child(3) { bottom: 25%; left: 35%; animation-delay: 1.6s; font-size: 40px; }
    .creators-sparkle:nth-child(4) { top: 15%; right: 35%; animation-delay: 2.2s; font-size: 20px; }
    @keyframes sparkle {
      0%, 100% { opacity: 0.4; transform: scale(1) rotate(0deg); }
      50% { opacity: 1; transform: scale(1.2) rotate(15deg); }
    }

    @media (max-width: 768px) {
      .creators-inner { grid-template-columns: 1fr; gap: 40px; }
      .creators-visual { max-height: 300px; }
    }

    /* ============ TAGLINE BANNER ============ */
    .tagline-banner {
      padding: 80px 0; text-align: center;
      background: var(--gradient); position: relative; overflow: hidden;
    }
    .tagline-banner::before {
      content: ''; position: absolute; inset: 0;
      background: radial-gradient(circle at 30% 50%, oklch(100% 0 0 / 0.1), transparent 60%);
    }
    .tagline-banner h2 {
      font-size: clamp(28px, 5vw, 56px); font-weight: 900;
      color: var(--bg-white); letter-spacing: -1px; line-height: 1.15;
      position: relative; z-index: 1;
    }

    /* ============ NEWS ============ */
    .news { background: var(--bg-white); }
    .news-header {
      display: flex; align-items: flex-end; justify-content: space-between;
